cd ~/Documents/systemcicy && grep -rn '\[`[^`]*`\](' --include='*.md' . | awk -F'\\[`' '{print}' | grep -oE '\[`[^`]+`\]\([^)]+\)' | sort -u | awk '{ if (match($0, /\[`([^`]+)`\]\(([^)]+)\)/, m)) { } }' 2>/dev/null | head -1; python3 - <<'PY'
import re,pathlib
for repo in ["/Users/taha/Documents/systemcicy","/Users/taha/Documents/webcrab"]:
    for p in pathlib.Path(repo).rglob("*.md"):
        if ".git" in str(p): continue
        for m in re.finditer(r'\[`([^`]+)`\]\(([^)]+)\)', p.read_text()):
            disp, tgt = m.group(1), m.group(2)
            if tgt.startswith("http") or tgt.startswith("#"): continue
            if disp.lstrip("./") != tgt.lstrip("./"):
                # allow ../ prefix differences only if basename+parent match
                if disp.split("/")[-2:] != tgt.split("/")[-2:]:
                    print(f"{p.relative_to(repo)}: display `{disp}` vs target ({tgt})")
PY
